f * Mathf.Deg2Rad; for (int i = 0; i \u003c overdrawLayers; i++) { float d = cam.nearClipPlane + 0.05f + i * 0.001f; float h = 2f * d * Mathf.Tan(halfFov) * 1.1f; GameObject quad = GameObject.CreatePrimitive(PrimitiveType.Quad); Collider col = quad.GetComponent\u003cCollider\u003e(); if (col != null) Destroy(col); quad.name = \\\"Overdraw_\\\" + i; quad.transform.SetParent(cam.transform, false); quad.transform.localPosition = new Vector3(0f, 0f, d); quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f); quad.GetComponent\u003cRenderer\u003e().sharedMaterial = overdrawMaterial; } } private void Update() { if (stressCpu && CachedObjects.Count \u003e 0) { for (int k = 0; k \u003c cpuScansPerFrame; k++) { int count = CachedObjects.Count; for (int i = 0; i \u003c count; i++) { GameObject obj = CachedObjects[i]; if (obj != null) { Vector3 pos = obj.transform.position; } } } } if (stressDraw && testPrefab != null) { int n = Mathf.Max(1, cubesPerFrame); for (int i = 0; i \u003c n; i++) { SpawnOne(); } } } private void SpawnOne() { GameObject clone = Instantiate(testPrefab, UnityEngine.Random.insideUnitSphere * spawnRadius, Quaternion.identity); CachedObjects.Add(clone); if (useUniqueMaterials) { Renderer rend = clone.GetComponent\u003cRenderer\u003e(); if (rend != null) { rend.GetPropertyBlock(_propBlock); _propBlock.SetColor(ColorProperty, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value)); rend.SetPropertyBlock(_propBlock); } } } private void OnDestroy() { CachedObjects.Clear(); } } }\",\"explicacao_didatica\":\"Metodos como FindObjectsOfType vasculham a memoria inteira procurando objetos, como revirar uma biblioteca inteira do zero a cada frame para achar um livro. Para resolver isso, guardamos referencias em uma lista previamente carregada (cache). Alem disso, concatenar strings com + dentro do Update cria copias temporarias na memoria que sobrecarregam o Garbage Collector (o lixeiro do Unity), gerando pequenos congelamento